<template><main class="team-home"><p v-if="loading">Loading team…</p><p v-else-if="error" role="alert">{{ error }}</p><template v-else-if="context"><header><TeamLogo :src="context.team.logoUrl" :name="context.team.name" :size="96"/><div><p class="eyebrow">TEAM HOME</p><h1>{{ context.team.name }}</h1><p>{{ gameLabel }} · {{ context.team.status }} · {{ context.teamRole || 'Platform administrator' }}</p><span v-if="context.team.entitlement?.isPro" class="pro">PRO</span><span v-else class="free">FREE</span></div></header><section><h2>Team summary</h2><div class="summary"><article><strong>Manager</strong><span>{{ member('MANAGER')?.displayName || 'Not assigned' }}</span></article><article><strong>Coach</strong><span>{{ member('COACH')?.displayName || 'Not assigned' }}</span></article><article><strong>Starting roster</strong><span>{{ starters.length }}/5</span></article><article><strong>Substitutes</strong><span>{{ substitutes.length }}</span></article></div></section><section><h2>Quick actions</h2><div class="actions"><RouterLink v-if="context.capabilities.canManageMembers" :to="`${base}/manage`">Manage team</RouterLink><RouterLink v-if="context.capabilities.canReviewChampionPools" :to="`${base}/coach-review`">{{ context.teamRole === 'MANAGER' ? 'View champion pools' : 'Review champion pools' }}</RouterLink><RouterLink v-if="context.capabilities.canEditChampionPool" :to="`${base}/champion-pool`">Update champion pool</RouterLink></div><p v-if="!actionsAvailable">No operational actions are assigned to this membership.</p></section></template></main></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import TeamLogo from './TeamLogo.vue'; import { getTeamHub } from './teamHub.service.js';
const route=useRoute(), context=ref(null), loading=ref(true), error=ref(''); const base=computed(()=>`/team-hub/${context.value?.team?.slug||''}`); const gameLabel=computed(()=>context.value?.team?.gameKey==='LEAGUE_OF_LEGENDS'?'League of Legends':context.value?.team?.gameKey); const starters=computed(()=>(context.value?.roster||[]).filter(x=>x.slotType==='STARTER')); const substitutes=computed(()=>(context.value?.roster||[]).filter(x=>x.slotType==='SUBSTITUTE')); const member=(role)=>(context.value?.members||[]).find(x=>x.role===role&&x.status==='ACTIVE'); const actionsAvailable=computed(()=>Object.values(context.value?.capabilities||{}).some(Boolean)); onMounted(async()=>{try{context.value=await getTeamHub({teamSlug:String(route.params.teamSlug||'')})}catch(e){error.value=e instanceof Error?e.message:'Unable to load team.'}finally{loading.value=false}});
</script>
<style scoped>.team-home{min-height:70vh;padding:32px clamp(18px,5vw,72px);color:#f5f6fa;background:#080a0f}.team-home header{display:flex;align-items:center;gap:22px}.team-home h1{margin:2px 0}.eyebrow{color:#a9ff38;font-weight:800}.pro,.free{display:inline-block;padding:5px 10px;border-radius:999px;border:1px solid #a46bff}.free{border-color:#69707c}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.summary article{display:grid;gap:8px;padding:18px;border:1px solid #303641;border-radius:12px;background:#11151c}.summary span{color:#b6bdc8}.actions{display:flex;gap:12px;flex-wrap:wrap}.actions a{padding:11px 16px;border-radius:8px;background:#7036c5;color:#fff;text-decoration:none}section{margin-top:28px}</style>
